function productExceptSelf(nums: number[]): number[] {
  const n = nums.length;
  const answer = new Array<number>(n);

  // Проход слева направо: answer[i] = произведение всех элементов левее i
  let prefix = 1;
  for (let i = 0; i < n; i++) {
    answer[i] = prefix;
    prefix *= nums[i];
  }

  // Проход справа налево: домножаем на произведение всех элементов правее i
  let suffix = 1;
  for (let i = n - 1; i >= 0; i--) {
    answer[i] *= suffix;
    suffix *= nums[i];
  }

  return answer;
}

// Время: O(n) — два прохода
// Память: O(1) дополнительно (выходной массив не считается)
